/** Job types, request validation, and API error helpers shared by the server and worker. */

export const JOB_STATUSES = ['queued', 'running', 'completed', 'failed'] as const;
export type JobStatus = (typeof JOB_STATUSES)[number];

export const DEFAULT_STEPS = 5;
export const DEFAULT_FAIL_ATTEMPTS = 0;
export const MIN_STEPS = 1;
export const MAX_STEPS = 20;
export const MIN_FAIL_ATTEMPTS = 0;
export const MAX_FAIL_ATTEMPTS = 5;
export const MAX_INPUT_LENGTH = 1000;
/** Upper bound on the raw request body. Far above any valid submission. */
export const MAX_BODY_BYTES = 64 * 1024;
export const IDEMPOTENCY_KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;

/** The public job shape returned by every endpoint that returns a job. */
export interface PublicJob {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

/** The normalized, validated submission (defaults applied). */
export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

export interface FieldError {
  field: string;
  message: string;
}

/** An error that maps directly to an API error response. */
export class ApiError extends Error {
  constructor(
    readonly status: number,
    readonly code: string,
    message: string,
    readonly fields?: FieldError[],
  ) {
    super(message);
    this.name = 'ApiError';
  }
}

export interface RawSubmission {
  contentType: string | undefined;
  /** Raw body text; empty when `problem` is set. */
  body: string;
  /** Set when the body could not be read or exceeded the size limit. */
  problem?: 'too_large' | 'read_error';
  /** Every value sent for the Idempotency-Key header, in order. */
  idempotencyKeyValues: string[];
}

export interface ValidatedSubmission {
  job: NewJob;
  idempotencyKey: string | null;
}

const ALLOWED_FIELDS = ['input', 'steps', 'failAttempts'] as const;

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

/** True for `application/json` with any parameters, matched case-insensitively. */
export function isJsonContentType(contentType: string | undefined): boolean {
  if (contentType === undefined) return false;
  return contentType.split(';')[0]!.trim().toLowerCase() === 'application/json';
}

/**
 * Validates a POST /api/jobs submission. Collects every independently detectable error so the
 * caller sees all of them at once. Never applies defaults to explicit null or wrong-typed values.
 */
export function validateSubmission(raw: RawSubmission): ValidatedSubmission {
  const fields: FieldError[] = [];
  let bodyUsable = true;

  if (!isJsonContentType(raw.contentType)) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
    bodyUsable = false;
  }
  if (raw.problem === 'too_large') {
    fields.push({ field: 'body', message: `Request body must be at most ${MAX_BODY_BYTES} bytes` });
    bodyUsable = false;
  } else if (raw.problem === 'read_error') {
    fields.push({ field: 'body', message: 'Request body could not be read' });
    bodyUsable = false;
  }

  let parsed: unknown;
  if (bodyUsable) {
    try {
      parsed = JSON.parse(raw.body);
    } catch {
      fields.push({ field: 'body', message: 'Request body is not valid JSON' });
      bodyUsable = false;
    }
  }
  if (bodyUsable && !isPlainObject(parsed)) {
    fields.push({ field: 'body', message: 'Request body must be a JSON object' });
    bodyUsable = false;
  }

  let job: NewJob | undefined;
  if (bodyUsable && isPlainObject(parsed)) {
    job = validateFields(parsed, fields);
  }

  const idempotencyKey = validateIdempotencyKey(raw.idempotencyKeyValues, fields);

  if (fields.length > 0 || job === undefined) {
    throw new ApiError(400, 'invalid_request', 'The submission is invalid.', fields.length > 0 ? fields : [{ field: 'body', message: 'Request body is invalid' }]);
  }
  return { job, idempotencyKey };
}

function validateFields(obj: Record<string, unknown>, fields: FieldError[]): NewJob | undefined {
  const allowed: readonly string[] = ALLOWED_FIELDS;
  for (const key of Object.keys(obj)) {
    if (!allowed.includes(key)) fields.push({ field: key, message: 'Unknown field' });
  }

  let input: string | undefined;
  if (!Object.hasOwn(obj, 'input')) {
    fields.push({ field: 'input', message: 'Field is required' });
  } else if (typeof obj.input !== 'string') {
    fields.push({ field: 'input', message: 'Must be a string' });
  } else if (obj.input.length < 1 || obj.input.length > MAX_INPUT_LENGTH) {
    fields.push({ field: 'input', message: `Must be 1 to ${MAX_INPUT_LENGTH} characters` });
  } else if (obj.input.trim().length === 0) {
    fields.push({ field: 'input', message: 'Must not be blank' });
  } else {
    input = obj.input;
  }

  const steps = integerField(obj, 'steps', DEFAULT_STEPS, MIN_STEPS, MAX_STEPS, fields);
  const failAttempts = integerField(obj, 'failAttempts', DEFAULT_FAIL_ATTEMPTS, MIN_FAIL_ATTEMPTS, MAX_FAIL_ATTEMPTS, fields);

  if (input === undefined || steps === undefined || failAttempts === undefined) return undefined;
  return { input, steps, failAttempts };
}

function integerField(obj: Record<string, unknown>, name: string, fallback: number, min: number, max: number, fields: FieldError[]): number | undefined {
  if (!Object.hasOwn(obj, name)) return fallback;
  const value = obj[name];
  if (typeof value !== 'number' || !Number.isInteger(value) || value < min || value > max) {
    fields.push({ field: name, message: `Must be an integer from ${min} to ${max}` });
    return undefined;
  }
  return value;
}

function validateIdempotencyKey(values: string[], fields: FieldError[]): string | null {
  if (values.length === 0) return null;
  if (values.length > 1) {
    fields.push({ field: 'Idempotency-Key', message: 'Must be sent exactly once' });
    return null;
  }
  const key = values[0]!;
  if (!IDEMPOTENCY_KEY_PATTERN.test(key)) {
    fields.push({ field: 'Idempotency-Key', message: 'Must be 1 to 128 characters: letters, digits, underscore, or hyphen' });
    return null;
  }
  return key;
}

