import { DatabaseSync, type StatementSync } from 'node:sqlite';
import { randomUUID } from 'node:crypto';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { ApiError, type JobStatus, type NewJob, type PublicJob } from './jobs.ts';

/** A worker heartbeat older than this means the worker is down. */
export const HEARTBEAT_STALE_MS = 3000;

const SCHEMA = `
CREATE TABLE IF NOT EXISTS jobs (
  seq INTEGER PRIMARY KEY AUTOINCREMENT,
  id TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL CHECK (status IN ('queued', 'running', 'completed', 'failed')),
  input TEXT NOT NULL,
  steps INTEGER NOT NULL,
  fail_attempts INTEGER NOT NULL,
  attempts INTEGER NOT NULL DEFAULT 0,
  completed INTEGER NOT NULL DEFAULT 0,
  output TEXT,
  error TEXT,
  idempotency_key TEXT UNIQUE,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  retry_at INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS jobs_claim ON jobs (status, retry_at, seq);
CREATE TABLE IF NOT EXISTS worker_heartbeat (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  seen_at INTEGER NOT NULL
);
`;

/** Opens the SQLite database shared by the server and worker processes and ensures the schema exists. */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
  // CREATE ... IF NOT EXISTS is idempotent, so either process may run it first.
  db.exec(SCHEMA);
  return db;
}

/** A row of the `jobs` table, as stored. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  completed: number;
  output: string | null;
  error: string | null;
  idempotency_key: string | null;
  created_at: string;
  updated_at: string;
  retry_at: number;
}

/** A job the worker has marked running for one attempt. */
export interface ClaimedJob {
  seq: number;
  id: string;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  /** True when the job was already running (interrupted by a previous worker process). */
  recovered: boolean;
}

/** Converts a stored row to the public job shape. */
export function serializeJob(row: JobRow): PublicJob {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed, total: row.steps },
    result: row.status === 'completed' && row.output !== null ? { output: row.output } : null,
    error: row.status === 'failed' && row.error !== null ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

/** Prepared queries and transactional operations over the shared database. */
export class Store {
  private readonly insertJob: StatementSync;
  private readonly selectByKey: StatementSync;
  private readonly selectById: StatementSync;
  private readonly selectAll: StatementSync;
  private readonly selectNext: StatementSync;
  private readonly claimJob: StatementSync;
  private readonly updateProgress: StatementSync;
  private readonly completeJob: StatementSync;
  private readonly requeueJob: StatementSync;
  private readonly failJob: StatementSync;
  private readonly upsertHeartbeat: StatementSync;
  private readonly selectHeartbeat: StatementSync;
  private readonly deleteHeartbeat: StatementSync;

  constructor(readonly db: DatabaseSync) {
    this.insertJob = db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, output, error, idempotency_key, created_at, updated_at, retry_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, ?, ?, ?, 0)`,
    );
    this.selectByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
    this.selectById = db.prepare('SELECT * FROM jobs WHERE id = ?');
    this.selectAll = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
    // Running jobs (interrupted attempts) come first; then the oldest eligible queued job.
    this.selectNext = db.prepare(
      `SELECT * FROM jobs
        WHERE status = 'running' OR (status = 'queued' AND retry_at <= ?)
        ORDER BY (status = 'running') DESC, seq ASC
        LIMIT 1`,
    );
    this.claimJob = db.prepare(
      `UPDATE jobs
          SET status = 'running', attempts = ?, completed = 0, output = NULL, error = NULL, retry_at = 0, updated_at = ?
        WHERE seq = ?`,
    );
    this.updateProgress = db.prepare('UPDATE jobs SET completed = ?, updated_at = ? WHERE seq = ?');
    this.completeJob = db.prepare(
      `UPDATE jobs SET status = 'completed', completed = steps, output = ?, error = NULL, retry_at = 0, updated_at = ? WHERE seq = ?`,
    );
    this.requeueJob = db.prepare(
      `UPDATE jobs SET status = 'queued', completed = 0, retry_at = ?, updated_at = ? WHERE seq = ?`,
    );
    this.failJob = db.prepare(
      `UPDATE jobs SET status = 'failed', completed = 0, output = NULL, error = ?, retry_at = 0, updated_at = ? WHERE seq = ?`,
    );
    this.upsertHeartbeat = db.prepare(
      'INSERT INTO worker_heartbeat (id, seen_at) VALUES (1, ?) ON CONFLICT (id) DO UPDATE SET seen_at = excluded.seen_at',
    );
    this.selectHeartbeat = db.prepare('SELECT seen_at FROM worker_heartbeat WHERE id = 1');
    this.deleteHeartbeat = db.prepare('DELETE FROM worker_heartbeat WHERE id = 1');
  }

  close(): void {
    this.db.close();
  }

  /** Runs `fn` in a BEGIN IMMEDIATE transaction. `fn` must not await. */
  transaction<T>(fn: () => T): T {
    this.db.exec('BEGIN IMMEDIATE');
    let result: T;
    try {
      result = fn();
      this.db.exec('COMMIT');
    } catch (e) {
      try {
        this.db.exec('ROLLBACK');
      } catch {
        // The transaction may already be closed; the original error is the one to report.
      }
      throw e;
    }
    return result;
  }

  /**
   * Creates a job, or replays/conflicts with an existing job that used the same idempotency key.
   * The returned job is the queued snapshot captured before commit.
   */
  submit(job: NewJob, idempotencyKey: string | null): { created: boolean; job: PublicJob } {
    return this.transaction(() => {
      if (idempotencyKey !== null) {
        const existing = this.selectByKey.get(idempotencyKey) as unknown as JobRow | undefined;
        if (existing) {
          const same = existing.input === job.input && existing.steps === job.steps && existing.fail_attempts === job.failAttempts;
          if (!same) {
            throw new ApiError(409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different submission.');
          }
          return { created: false, job: serializeJob(existing) };
        }
      }
      const id = randomUUID();
      const now = new Date().toISOString();
      this.insertJob.run(id, job.input, job.steps, job.failAttempts, idempotencyKey, now, now);
      const snapshot = serializeJob({
        seq: 0,
        id,
        status: 'queued',
        input: job.input,
        steps: job.steps,
        fail_attempts: job.failAttempts,
        attempts: 0,
        completed: 0,
        output: null,
        error: null,
        idempotency_key: idempotencyKey,
        created_at: now,
        updated_at: now,
        retry_at: 0,
      });
      return { created: true, job: snapshot };
    });
  }

  listJobs(): PublicJob[] {
    return (this.selectAll.all() as unknown as JobRow[]).map(serializeJob);
  }

  getJob(id: string): PublicJob | undefined {
    const row = this.selectById.get(id) as unknown as JobRow | undefined;
    return row ? serializeJob(row) : undefined;
  }

  /** Worker-side: claims the next job to run, marking it running. */
  claimNext(nowMs: number): ClaimedJob | undefined {
    return this.transaction(() => {
      const row = this.selectNext.get(nowMs) as unknown as JobRow | undefined;
      if (!row) return undefined;
      const recovered = row.status === 'running';
      // A recovered attempt keeps its persisted number; it is re-executed, not counted again.
      const attempts = recovered ? row.attempts : row.attempts + 1;
      this.claimJob.run(attempts, new Date().toISOString(), row.seq);
      return {
        seq: row.seq,
        id: row.id,
        input: row.input,
        steps: row.steps,
        failAttempts: row.fail_attempts,
        attempts,
        recovered,
      };
    });
  }

  recordProgress(seq: number, completed: number): void {
    this.updateProgress.run(completed, new Date().toISOString(), seq);
  }

  complete(seq: number, output: string): void {
    this.completeJob.run(output, new Date().toISOString(), seq);
  }

  requeue(seq: number, retryAtMs: number): void {
    this.requeueJob.run(retryAtMs, new Date().toISOString(), seq);
  }

  fail(seq: number, error: string): void {
    this.failJob.run(error, new Date().toISOString(), seq);
  }

  writeHeartbeat(nowMs: number): void {
    this.upsertHeartbeat.run(nowMs);
  }

  clearHeartbeat(): void {
    this.deleteHeartbeat.run();
  }

  workerUp(nowMs: number): boolean {
    const row = this.selectHeartbeat.get() as { seen_at: number } | undefined;
    return row !== undefined && nowMs - Number(row.seen_at) <= HEARTBEAT_STALE_MS;
  }
}

