  }

  complete(seq: number, output: string): void {
    this.completeJob.run(output, new Date().toISOString(), seq);
  }

  requeue(seq: number, retryAtMs: number): void {
    this.requeueJob.run(retryAtMs, new Date().toISOString(), seq);
  }

  fail(seq: number, error: string): void {
    this.failJob.run(error, new Date().toISOString(), seq);
  }

  writeHeartbeat(nowMs: number): void {
    this.upsertHeartbeat.run(nowMs);
  }

  clearHeartbeat(): void {
    this.deleteHeartbeat.run();
  }

  workerUp(nowMs: number): boolean {
    const row = this.selectHeartbeat.get() as { seen_at: number } | undefined;
    return row !== undefined && nowMs - Number(row.seen_at) <= HEARTBEAT_STALE_MS;
  }
}

