import { openDatabase, Store } from './db.ts';
import type { ClaimedJob } from './db.ts';

/** Time spent on each processing step. */
const STEP_MS = 100;
/** Delay before a failed attempt is retried. */
const RETRY_DELAY_MS = 500;
/** Attempts allowed in total before a job is failed. */
const MAX_ATTEMPTS = 3;
/** How often the worker refreshes its heartbeat. */
const HEARTBEAT_MS = 500;
/** How long an idle worker waits before checking for work again. */
const IDLE_POLL_MS = 100;

/** Resolves after `ms`, or as soon as `signal` aborts. Never rejects. */
function pause(ms: number, signal: AbortSignal): Promise<void> {
  return new Promise((resolve) => {
    if (signal.aborted) return resolve();
    const timer = setTimeout(done, ms);
    function done(): void {
      clearTimeout(timer);
      signal.removeEventListener('abort', done);
      resolve();
    }
    signal.addEventListener('abort', done, { once: true });
  });
}

/**
 * Runs one attempt. Every database write is a short synchronous statement, so nothing is held
 * open across the awaits. If shutdown interrupts a step, the job is left `running` and is
 * re-executed from progress zero by the next worker start.
 */
async function runAttempt(store: Store, job: ClaimedJob, signal: AbortSignal): Promise<void> {
  if (job.attempts <= job.failAttempts) {
    // Simulated transient failure at the first step, before any progress is recorded.
    await pause(STEP_MS, signal);
    if (signal.aborted) return;
    if (job.attempts >= MAX_ATTEMPTS) {
      store.fail(job.seq, 'transient failure');
    } else {
      store.requeue(job.seq, Date.now() + RETRY_DELAY_MS);
    }
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await pause(STEP_MS, signal);
    if (signal.aborted) return;
    if (step === job.steps) {
      store.complete(job.seq, job.input.toUpperCase());
    } else {
      store.recordProgress(job.seq, step);
    }
  }
}

async function main(): Promise<void> {
  const store = new Store(openDatabase());
  const controller = new AbortController();
  const { signal } = controller;
  let exitCode = 0;

  const shutdown = (): void => {
    if (signal.aborted) return;
    console.log('worker stopping');
    controller.abort();
  };
  process.once('SIGTERM', shutdown);
  process.once('SIGINT', shutdown);

  const beat = (): void => {
    try {
      store.writeHeartbeat(Date.now());
    } catch (e) {
      console.error('heartbeat failed:', e instanceof Error ? e.message : e);
    }
  };
  beat();
  const heartbeat = setInterval(beat, HEARTBEAT_MS);

  console.log('worker started');
  try {
    while (!signal.aborted) {
      const job = store.claimNext(Date.now());
      if (!job) {
        await pause(IDLE_POLL_MS, signal);
        continue;
      }
      if (job.recovered) console.log(`re-running interrupted job ${job.id} (attempt ${job.attempts})`);
      await runAttempt(store, job, signal);
    }
  } catch (e) {
    console.error('worker error:', e instanceof Error ? e.stack ?? e.message : e);
    exitCode = 1;
  } finally {
    clearInterval(heartbeat);
    try {
      store.clearHeartbeat();
    } catch {
      // Ignored: the stale heartbeat expires on its own within 3 seconds.
    }
    store.close();
    console.log('worker stopped');
    process.exitCode = exitCode;
  }
}

await main();

