import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase, Store } from './db.ts';
import { ApiError, MAX_BODY_BYTES, validateSubmission, type FieldError, type RawSubmission } from './jobs.ts';

/** Time allowed for in-flight requests to finish after a shutdown signal. */
const DRAIN_MS = 3000;

const store = new Store(openDatabase());
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function sendJson(res: ServerResponse, status: number, body: unknown, extraHeaders: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...extraHeaders });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[], extraHeaders?: Record<string, string>): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  sendJson(res, status, { error }, extraHeaders);
}

function methodNotAllowed(res: ServerResponse, allowed: string[]): void {
  sendError(res, 405, 'method_not_allowed', `Method not allowed. Allowed: ${allowed.join(', ')}`, undefined, { allow: allowed.join(', ') });
}

/** Reads the whole request body as text, up to MAX_BODY_BYTES. */
function readBody(req: IncomingMessage): Promise<Pick<RawSubmission, 'body' | 'problem'>> {
  return new Promise((resolve) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      if (tooLarge) return;
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        chunks.length = 0;
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => {
      if (tooLarge) resolve({ body: '', problem: 'too_large' });
      else resolve({ body: Buffer.concat(chunks).toString('utf8') });
    });
    req.on('error', () => resolve({ body: '', problem: 'read_error' }));
    req.on('aborted', () => resolve({ body: '', problem: 'read_error' }));
  });
}

function idempotencyKeyValues(req: IncomingMessage): string[] {
  const values: string[] = [];
  const raw = req.rawHeaders;
  for (let i = 0; i < raw.length; i += 2) {
    if (raw[i]!.toLowerCase() === 'idempotency-key') values.push(raw[i + 1] ?? '');
  }
  return values;
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const read = await readBody(req);
  if (read.problem === 'too_large') res.setHeader('connection', 'close');
  const submission = validateSubmission({
    contentType: req.headers['content-type'],
    body: read.body,
    problem: read.problem,
    idempotencyKeyValues: idempotencyKeyValues(req),
  });
  const result = store.submit(submission.job, submission.idempotencyKey);
  sendJson(res, result.created ? 201 : 200, result.job);
}

function listJobs(res: ServerResponse): void {
  sendJson(res, 200, { jobs: store.listJobs() });
}

function getJob(res: ServerResponse, rawId: string): void {
  let id: string;
  try {
    id = decodeURIComponent(rawId);
  } catch {
    sendError(res, 404, 'not_found', 'No job with that id');
    return;
  }
  const job = store.getJob(id);
  if (!job) {
    sendError(res, 404, 'not_found', 'No job with that id');
    return;
  }
  sendJson(res, 200, job);
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const method = req.method ?? 'GET';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');

  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    const up = store.workerUp(Date.now());
    sendJson(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
    return;
  }

  if (pathname === '/api/jobs') {
    if (method === 'GET') return listJobs(res);
    if (method === 'POST') return createJob(req, res);
    return methodNotAllowed(res, ['GET', 'POST']);
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    return getJob(res, match[1]!);
  }

  sendError(res, 404, 'not_found', 'No such route');
}

const server = createServer((req, res) => {
  route(req, res).catch((err: unknown) => {
    if (err instanceof ApiError) {
      sendError(res, err.status, err.code, err.message, err.fields);
      return;
    }
    console.error('request failed:', err instanceof Error ? err.stack ?? err.message : err);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Unexpected server error');
    else res.end();
  });
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  console.log('server stopping');
  server.close(() => {
    store.close();
    console.log('server stopped');
  });
  // Idle keep-alive sockets are closed by server.close(); this bounds requests that never finish.
  const force = setTimeout(() => server.closeAllConnections(), DRAIN_MS);
  force.unref();
}
process.once('SIGTERM', shutdown);
process.once('SIGINT', shutdown);

