const procs = {};
function start(name) {
  procs[name] = spawn('node', ['--disable-warning=ExperimentalWarning', `${APP}/dist/${name}.js`], { env, stdio: ['ignore', 'pipe', 'pipe'] });
  procs[name].stderr.on('data', (d) => process.stderr.write(`[${name} err] ${d}`));
}
const req = async (method, path, body, headers = {}) => {
  const r = await fetch(base + path, { method, headers: body === undefined ? headers : { 'content-type': 'application/json', ...headers }, body: body === undefined ? undefined : (typeof body === 'string' ? body : JSON.stringify(body)) });
  const text = await r.text();
  let json; try { json = JSON.parse(text) } catch {}
  return { status: r.status, json, text, ct: r.headers.get('content-type') };
};
const waitDone = async (id, ms = 15000) => {
  const t0 = Date.now();
  for (;;) {
    const j = (await req('GET', `/api/jobs/${id}`)).json;
    if (j.status === 'completed' || j.status === 'failed') return { job: j, ms: Date.now() - t0 };
    if (Date.now() - t0 > ms) throw new Error('timeout ' + id);
    await sleep(50);
  }
};
const results = [];
const check = (name, ok, extra = '') => { results.push(ok); console.log(`${ok ? 'PASS' : 'FAIL'} ${name} ${ok ? '' : extra}`); };

start('server'); start('worker');
await sleep(1500);
let h = (await req('GET', '/health')).json;
check('health worker up', h.worker === 'up', JSON.stringify(h));

// Retries
for (const [fa, expectStatus, expectAttempts] of [[0,'completed',1],[1,'completed',2],[2,'completed',3],[3,'failed',3],[5,'failed',3]]) {
  const c = await req('POST', '/api/jobs', { input: `r${fa}`, steps: 2, failAttempts: fa });
  check(`create fa=${fa} 201 queued`, c.status === 201 && c.json.status === 'queued', c.text);
  const { job } = await waitDone(c.json.id);
  check(`fa=${fa} -> ${expectStatus}, attempts ${expectAttempts}`, job.status === expectStatus && job.attempts === expectAttempts, JSON.stringify(job));
  if (expectStatus === 'failed') check(`fa=${fa} error text`, job.error === 'transient failure' && job.result === null && job.progress.completed === 0, JSON.stringify(job));
  else check(`fa=${fa} output`, job.result?.output === `R${fa}` && job.progress.completed === 2, JSON.stringify(job));
}

// Validation
const bad = [
  ['malformed', '{', {}], ['array', '[]', {}], ['null', 'null', {}],
  ['null steps', { input: 'a', steps: null }, {}], ['fraction', { input: 'a', steps: 2.5 }, {}],
  ['string steps', { input: 'a', steps: '3' }, {}], ['blank', { input: '   ' }, {}],
  ['too long', { input: 'x'.repeat(1001) }, {}], ['unknown', { input: 'a', foo: 1 }, {}],
  ['multi', { steps: 99, failAttempts: -1 }, {}],
  ['bad key', { input: 'a' }, { 'idempotency-key': 'has space' }],
];
const before = (await req('GET', '/api/jobs')).json.jobs.length;
for (const [name, body, headers] of bad) {
  const r = await req('POST', '/api/jobs', body, headers);
  check(`invalid ${name} 400`, r.status === 400 && r.json?.error?.code === 'invalid_request' && Array.isArray(r.json.error.fields), r.text);
}
const noCt = await fetch(base + '/api/jobs', { method: 'POST', body: '{"input":"a"}' });
check('missing content-type 400', noCt.status === 400);
const multi = (await req('POST', '/api/jobs', { steps: 99, failAttempts: -1 })).json;
check('multi fields listed', multi.error.fields.map(f=>f.field).sort().join() === 'failAttempts,input,steps', JSON.stringify(multi));
const after = (await req('GET', '/api/jobs')).json.jobs.length;
check('invalid created no jobs', before === after, `${before} vs ${after}`);
check('charset param accepted', (await req('POST', '/api/jobs', {input:'cs'}, {'content-type':'Application/JSON; charset=utf-8'})).status === 201);

// Idempotency
const k1 = await req('POST', '/api/jobs', { input: 'idem' }, { 'idempotency-key': 'key-A' });
const k2 = await req('POST', '/api/jobs', { input: 'idem', steps: 5, failAttempts: 0 }, { 'idempotency-key': 'key-A' });
check('idem 201 then 200 same id', k1.status === 201 && k2.status === 200 && k1.json.id === k2.json.id);
const k3 = await req('POST', '/api/jobs', { input: 'idem2' }, { 'idempotency-key': 'key-A' });
check('idem conflict 409', k3.status === 409 && k3.json.error.code === 'idempotency_conflict');
const conc = await Promise.all(Array.from({length: 8}, () => req('POST', '/api/jobs', { input: 'conc' }, { 'idempotency-key': 'key-C' })));
const ids = new Set(conc.map(r => r.json.id));
check('concurrent same-key one id', ids.size === 1 && conc.filter(r=>r.status===201).length === 1, JSON.stringify(conc.map(r=>r.status)));

// Routing
check('unknown path 404', (await req('GET', '/nope')).json?.error?.code === 'not_found');
check('missing id 404', (await req('GET', '/api/jobs/zzz')).status === 404);
check('wrong method on id 405', (await req('DELETE', '/api/jobs/zzz')).status === 405);
check('wrong method health 405', (await req('POST', '/health')).status === 405);
const ui = await req('GET', '/');
check('html served', ui.status === 200 && /text\/html/.test(ui.ct) && ui.text.includes('data-testid="job-form"'));

// Processing observed
const long = await req('POST', '/api/jobs', { input: 'long running', steps: 20 });
let sawRunning = false, sawMid = false;
for (let i=0;i<40;i++){ const j=(await req('GET', `/api/jobs/${long.json.id}`)).json; if (j.status==='running') sawRunning=true; if (j.status==='running' && j.progress.completed>0 && j.progress.completed<20) sawMid=true; await sleep(100); }
check('observed running and intermediate progress', sawRunning && sawMid);

// Durability: restart both
const idemBefore = k1.json.id;
const waiting = await req('POST', '/api/jobs', { input: 'queued during kill', steps: 3 });
procs.worker.kill('SIGKILL'); procs.server.kill('SIGKILL');
await sleep(300);
start('server'); start('worker');
await sleep(1500);
const replay = await req('POST', '/api/jobs', { input: 'idem' }, { 'idempotency-key': 'key-A' });
check('replay after restart returns same id 200', replay.status === 200 && replay.json.id === idemBefore, replay.text);
const fin = await waitDone(waiting.json.id);
check('queued job completes after restart', fin.job.status === 'completed' && fin.job.result.output === 'QUEUED DURING KILL', JSON.stringify(fin.job));
check('long job persisted completed', (await req('GET', `/api/jobs/${long.json.id}`)).json.status === 'completed');

// Heartbeat down after SIGKILL
procs.worker.kill('SIGKILL');
await sleep(3500);
h = (await req('GET', '/health')).json;
check('worker down after kill', h.worker === 'down', JSON.stringify(h));

// Graceful shutdown of server
const t0 = Date.now();
const exits = await Promise.all(['server'].map(n => new Promise(res => { procs[n].once('exit', (c)=>res([n,c])); procs[n].kill('SIGTERM'); })));
check('server SIGTERM exits cleanly', exits[0][1] === 0 && Date.now()-t0 < 4000, JSON.stringify(exits));

const failed = results.filter(x => !x).length;
console.log(failed ? `${failed} FAILED` : 'ALL PASSED');
process.exit(0);
